head.script:

scwin.onpageload = function() {

};

scwin.onpageunload = function() {

};

scwin.checkVal1 = function() {
	return document.getElementsByClassName('w2calendar_header_btn_close_yearType').length == 0;
}
scwin.checkVal2 = function() {
	return WebSquare.wUnit.getDomById('wq_uuid_6_calendar').style.display == 'none';
}	
scwin.unitTest = function() {
	//Unit
	WebSquare.wUnit.start();
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_6_img').click()");
	WebSquare.wUnit.addCommand("pause", "400");
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
	WebSquare.wUnit.addCommand("pause", "500");

	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_6_calendar_selectbox_year').click()");
	WebSquare.wUnit.addCommand("pause", "400");				
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_6_calendar_selectbox_year_itemTable_43').click()");
	WebSquare.wUnit.addCommand("pause", "400");	
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
	WebSquare.wUnit.addCommand("pause", "500");

	//Run test and stop
	WebSquare.wUnit.run();
	WebSquare.wUnit.stop();
}	
scwin.unitTest()
